import itertools
sheet = 'W1::Allowed assignments'
rows = data_rows(sheet, {'L':'string', 'M':'string', 'N':'number'}, start_row=812, end_row=820)
tasks = sorted(list(set(cell(sheet, f'L{r}') for r in rows)))
workers = sorted(list(set(cell(sheet, f'M{r}') for r in rows)))
costs = {(cell(sheet, f'L{r}'), cell(sheet, f'M{r}')): num(sheet, f'N{r}') for r in rows}
min_cost = float('inf')
for p in itertools.permutations(workers, len(tasks)):
    if all((tasks[i], p[i]) in costs for i in range(len(tasks))):
        c = sum(costs[(tasks[i], p[i])] for i in range(len(tasks)))
        if c < min_cost:
            min_cost = c
result = int(min_cost)

